def spread(X,F,nx,ny,nz,dx,dy,dz,ds,dV):
    G=ng((nx,ny,nz)); lag=[0.0]*3
    for x,ff in zip(X,F):
        i=min(nx-1,max(0,int(x[0]/dx))); j=min(ny-1,max(0,int(x[1]/dy))); k=min(nz-1,max(0,int(x[2]/dz)))
        for c in range(3): G[i][j][k][c]+=ff[c]*ds/dV; lag[c]+=ff[c]*ds
    integ=[0.0]*3
    for i in range(nx):
        for j in range(ny):
            for k in range(nz):
                for c in range(3): integ[c]+=G[i][j][k][c]*dV
    return G, lag, integ, [integ[c]-lag[c] for c in range(3)]

def run_case(lam, cfg):
    n,nx,ny,nz=cfg['n'],cfg['nx'],cfg['ny'],cfg['nz']; ds,dV=cfg['ds'],cfg['dV']; dt=cfg['dt']
    s=[i/(n-1) for i in range(n)]
    X=[[0.25+0.5*q,0.5+1e-4*math.sin(2*math.pi*q),0.5] for q in s]; V=[[0,0,0] for _ in range(n)]; A=[[0,0,0] for _ in range(n)]
    RHS0=ng((nx,ny,nz)); h={k:[] for k in 'X V A F_fs f_e fe rhs res disp bounded finite ar cons'.split()}; h['X'].append(X); h['V'].append(V); h['A'].append(A)
    for step in range(cfg['steps']):
        u=[[5e-4,1e-4*math.sin(2*math.pi*q+step*dt),0.0] for q in s]
        rel=[[u[i][c]-V[i][c] for c in range(3)] for i in range(n)]; ffs=[[cfg['cfs']*rel[i][c] for c in range(3)] for i in range(n)]
        fb=[[-cfg['bend']*(X[i][c]-h['X'][0][i][c]) for c in range(3)] for i in range(n)]; ft=[[-cfg['gamma']*V[i][c] for c in range(3)] for i in range(n)]
        F=[[fb[i][c]+ft[i][c]-ffs[i][c] for c in range(3)] for i in range(n)]; A=[[F[i][c]/cfg['rho_l'] for c in range(3)] for i in range(n)]
        Vn=[[V[i][c]+dt*A[i][c] for c in range(3)] for i in range(n)]; Xn=[[X[i][c]+dt*V[i][c]+0.5*dt*dt*A[i][c] for c in range(3)] for i in range(n)]
        f_struct=[[-ffs[i][c] for c in range(3)] for i in range(n)]; f_fluid=[[ffs[i][c] for c in range(3)] for i in range(n)]
        ar=math.sqrt(sum((f_struct[i][c]+f_fluid[i][c])**2 for i in range(n) for c in range(3)))
        fe,lag,ei,cons=spread(X,f_fluid,nx,ny,nz,cfg['dx'],cfg['dy'],cfg['dz'],ds,dV)
        delta=scale(lam,fe); after=add(RHS0,delta); resid=sub(delta,scale(lam,fe)); zerores=sub(after,RHS0)
        h['F_fs'].append(math.sqrt(sum(v*v for row in ffs for v in row))); h['f_e'].append(fe); h['fe'].append(grid_norm(fe)); h['rhs'].append(grid_norm(delta)); h['res'].append(grid_norm(resid if lam else zerores)); h['ar'].append(ar); h['cons'].append(math.sqrt(sum(v*v for v in cons)))
        h['disp'].append(max(abs(Xn[i][c]-h['X'][0][i][c]) for i in range(n) for c in range(3))); h['bounded'].append(h['disp'][-1] <= cfg['max_disp'] and grid_norm(delta) <= cfg['max_rhs']); h['finite'].append(finite([Xn,Vn,A,fe,after])); X,V=Xn,Vn; h['X'].append(X); h['V'].append(V); h['A'].append(A)
    return h

