        f.write(f"final_status {'PASS' if final else 'FAIL'}\nSTAGE 20.8 LAMBDA REGRESSION RESPONSE COMPARISON VERDICT: {'PASS' if final else 'FAIL'}\nSTAGE 20.8 FINAL VERDICT: {'PASS' if final else 'FAIL'}\n")
